(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['mass','rate','offset'],defaults={mass:5,rate:10,offset:0},get=k=>document.getElementById('T01-'+k);let state={};function update(){const m=+get('mass').value,rate=+get('rate').value,off=+get('offset').value,beta=rate/60,peak=m*beta*45/(5*Math.sqrt(2*Math.PI)),rows=Array.from({length:801},(_,i)=>{let t=145+i*.05;return[t,peak*Math.exp(-.5*((t-165)/5)**2)]});let area=0;for(let i=1;i<rows.length;i++)area+=.05*(rows[i-1][1]+rows[i][1])/2;state={mass:m,rate,offset:off,true_heat_J_per_g:45,window_heat_J_per_g:area/(m*beta),integrated_heat_J_per_g:(area-off*40)/(m*beta),baseline_error_J_per_g:-off*40/(m*beta),peak_mW:peak};keys.forEach(k=>get(k+'-value').textContent=(+get(k).value).toFixed(k==='offset'?3:1));get('result').textContent=(zh?'积分焓：':'Integrated enthalpy: ')+state.integrated_heat_J_per_g.toFixed(3)+' J/g; '+(zh?'基线贡献的偏差：':'Baseline contribution to error: ')+state.baseline_error_J_per_g.toFixed(3)+' J/g; '+(zh?'峰高：':'Peak height: ')+peak.toFixed(3)+' mW';const X=t=>75+(t-145)/40*635,Y=q=>305-(q+.05)/13*250;let out='<rect width="760" height="380" fill="#fcfbf7"/><path d="M75 45V305H710" fill="none" stroke="#61758a"/>';for(const y of [0,3,6,9,12])out+='<line x1="75" x2="710" y1="'+Y(y)+'" y2="'+Y(y)+'" stroke="#dce3e5"/><text x="65" y="'+(Y(y)+4)+'" font-size="12" text-anchor="end">'+y+'</text>';for(let t=145;t<=185;t+=10)out+='<text x="'+X(t)+'" y="327" text-anchor="middle" font-size="12">'+t+'</text>';out+='<path d="M75 '+Y(off)+'H710" stroke="#d35f47" stroke-dasharray="5 4"/><path d="'+rows.map((r,i)=>(i?'L':'M')+X(r[0]).toFixed(2)+' '+Y(r[1]).toFixed(2)).join(' ')+'" fill="none" stroke="#167d9a" stroke-width="2.5"/>';out+='<text x="80" y="25" font-size="13">'+(zh?'转变热流 / mW；红线为估计基线':'Transition heat flow / mW; red line: estimated baseline')+'</text><text x="395" y="355" text-anchor="middle" font-size="13">'+(zh?'温度 / °C':'Temperature / °C')+'</text>';get('plot').innerHTML=out;}function set(p){keys.forEach(k=>{if(p[k]!==undefined){const e=get(k);e.value=Math.max(+e.min,Math.min(+e.max,+p[k]));}});update();}keys.forEach(k=>get(k).addEventListener('input',update));get('reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};update();})();
